import{M as e,O as t,c as n,d as r,h as i,m as a,p as o}from"./runtime-core.esm-bundler-jC72uHyJ.js";import{t as s}from"./app-DCPmwgWY.js";var c=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S04/S04E07.html","title":"S04E07 The One Where Chandler Crosses the Line","lang":"zh-CN","frontmatter":{"title":"S04E07 The One Where Chandler Crosses the Line","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":80},"git":{"createdTime":1780654155000,"updatedTime":1785479208000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":4}]},"readingTime":{"minutes":33.64,"words":10092},"filePathRelative":"语言/英语/Friends老友记/S04/S04E07.md"}`),l={name:`S04E07.md`};function u(s,c,l,u,d,f){let p=e(`StickyAudio`),m=e(`AudioButton`);return t(),r(`div`,null,[i(p,{src:`/audio/friends-tv/S04/S04E07.mp3`,title:`S04E07 The One Where Chandler Crosses the Line`}),c[0]||=o(`<h1 id="the-one-where-chandler-crosses-the-line" tabindex="-1"><a class="header-anchor" href="#the-one-where-chandler-crosses-the-line"><span>The One Where Chandler Crosses the Line</span></a></h1><blockquote><p>80：第四季第七集：钱德勒越界的那一集</p></blockquote><p>The One Where Chandler Crosses a Line</p><blockquote><p>钱德勒穿过一条线的那个</p></blockquote><p><strong>Written by: Adam Chase</strong></p><blockquote><p>作者：亚当·蔡斯</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, everyone except Joey and Chandler are there eating breakfast.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，除了乔伊和钱德勒，所有人都在吃早餐。</em></p></blockquote>`,11),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`0.0`,duration:`5.832`}),c[1]||=a(),c[2]||=n(`strong`,null,`Chandler Bing:`,-1),c[3]||=a(` (entering in a bathrobe) I just walked in the bathroom and saw Kathy naked! It was like torture!`,-1),c[4]||=n(`blockquote`,null,[n(`p`,null,`（穿着浴衣进来）我刚走进浴室，看见凯西一丝不挂！真是折磨人！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`5.832`,duration:`5.112`}),c[5]||=a(),c[6]||=n(`strong`,null,`Ross Geller:`,-1),c[7]||=a(` Y'know if we ever go to war and you’re captured, you’re in for a big surprise.`,-1),c[8]||=n(`blockquote`,null,[n(`p`,null,`你知道，如果我们打仗，你被俘了，你会大吃一惊的。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`10.944`,duration:`33.768`}),c[9]||=a(),c[10]||=n(`strong`,null,`Chandler Bing:`,-1),c[11]||=a(` It just keeps getting worse and worse! Y'know? I mean it’s bad enough that I’m in love with my roommates girlfriend—which by the way, I think she knows. Because every time we’re in the room together there’s this weird like energy between us. And call me crazy, but I think she likes me too. And now I have seen her naked. I mean at least when I’ve seen her with clothes on, I could imagine her body was like covered in boles or something. But there are no boles, she’s smooth! Smooth! (leaves)`,-1),c[12]||=n(`blockquote`,null,[n(`p`,null,`情况越来越糟！你知道吗？我的意思是，我爱上我室友的女朋友已经够糟糕了，顺便说一句，我想她知道。因为每次我们在一起的时候，我们之间都有一种奇怪的能量。叫我疯子，但我想她也喜欢我。现在我看到她裸体。我的意思是，至少当我看到她穿着衣服的时候，我可以想象她的身体像是被树干或什么东西覆盖着。但是没有树干，她很光滑！光滑！（叶子）`)],-1),c[13]||=n(`p`,null,[n(`em`,null,`(Pause)`)],-1),c[14]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（停顿）`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`44.712`,duration:`3.192`}),c[15]||=a(),c[16]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[17]||=a(` Wow! Could everyone totally see up his robe?`,-1),c[18]||=n(`blockquote`,null,[n(`p`,null,`哇！每个人都能看到他的长袍吗？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`47.904`,duration:`1.608`}),c[19]||=o(` <strong>All:</strong> Yeah! Oh my God!<blockquote><p>是的！哦，我的上帝！</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Central Perk, Joey is getting a phone number from a woman (Casey) as Chandler watches from the doorway.</em></p><blockquote><p>🎬 <em>中央公园，钱德勒在门口看着乔伊从一个女人（凯西）那里得到一个电话号码。</em></p></blockquote>`,9),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`49.512`,duration:`1.008`}),c[20]||=a(),c[21]||=n(`strong`,null,`Casey:`,-1),c[22]||=a(` Here you go.`,-1),c[23]||=n(`blockquote`,null,[n(`p`,null,`给你。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`50.52`,duration:`4.104`}),c[24]||=a(),c[25]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[26]||=a(` Great! All right, so I’ll call you later.`,-1),c[27]||=n(`blockquote`,null,[n(`p`,null,`太好了！好吧，我待会儿给你打电话。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`54.624`,duration:`0.84`}),c[28]||=a(),c[29]||=n(`strong`,null,`Casey:`,-1),c[30]||=a(` Great! (leaves)`,-1),c[31]||=n(`blockquote`,null,[n(`p`,null,`太好了！（离开）`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`55.464`,duration:`3.456`}),c[32]||=a(),c[33]||=n(`strong`,null,`Chandler Bing:`,-1),c[34]||=a(` (rushing up) Hey-Hey-Hey! Who was that?`,-1),c[35]||=n(`blockquote`,null,[n(`p`,null,`（冲上来）嘿嘿！那是谁？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`58.92`,duration:`4.2`}),c[36]||=a(),c[37]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[38]||=a(` That would be Casey. We’re going out tonight.`,-1),c[39]||=n(`blockquote`,null,[n(`p`,null,`那就是凯西。我们今晚要出去。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`63.12`,duration:`9.576`}),c[40]||=a(),c[41]||=n(`strong`,null,`Chandler Bing:`,-1),c[42]||=a(` Goin’ out, huh? Wow! Wow! (Does a little celebration dance) So things didn’t work out with Kathy, huh? Bummer.`,-1),c[43]||=n(`blockquote`,null,[n(`p`,null,`出去，嗯？哇！哇！（跳了一支小小的庆祝舞）那么凯西的事就不顺利了，嗯？糟糕透了。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`72.696`,duration:`7.728`}),c[44]||=a(),c[45]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[46]||=a(` No, things are fine with Kathy. I’m having a late dinner with her tonight, right after my early dinner with Casey.`,-1),c[47]||=n(`blockquote`,null,[n(`p`,null,`不，凯西没事。我今晚要和她一起吃晚饭，就在我和凯西一起吃晚饭之后。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`80.424`,duration:`1.464`}),c[48]||=a(),c[49]||=n(`strong`,null,`Chandler Bing:`,-1),c[50]||=a(` (shocked) What?`,-1),c[51]||=n(`blockquote`,null,[n(`p`,null,`（震惊）什么？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`81.888`,duration:`5.928`}),c[52]||=a(),c[53]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[54]||=a(` Yeah-yeah. And the craziest thing is that I just ate a whole pizza by myself! (Laughs)`,-1),c[55]||=n(`blockquote`,null,[n(`p`,null,`是的，是的。最疯狂的事情是我一个人吃了整个比萨饼！（笑）`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`87.816`,duration:`3.84`}),c[56]||=a(),c[57]||=n(`strong`,null,`Chandler Bing:`,-1),c[58]||=a(` Wait! You’re going out with Kathy!`,-1),c[59]||=n(`blockquote`,null,[n(`p`,null,`等等！你要和凯西出去！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`91.656`,duration:`3.984`}),c[60]||=a(),c[61]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[62]||=a(` Yeah. Why are you getting so upset?`,-1),c[63]||=n(`blockquote`,null,[n(`p`,null,`是啊。你为什么这么不高兴？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`95.64`,duration:`9.0`}),c[64]||=a(),c[65]||=n(`strong`,null,`Chandler Bing:`,-1),c[66]||=a(` Well, I’m upset—for you. I mean, having sex with an endless line of beautiful women must be very unfulfilling for you. (He can’t believe he just sad that.)`,-1),c[67]||=n(`blockquote`,null,[n(`p`,null,`嗯，我为你感到难过。我是说，和无数美女做爱对你来说一定很不满足。（他不敢相信他会这么伤心。）`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`104.64`,duration:`4.752`}),c[68]||=a(),c[69]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[70]||=a(` What is the big deal? It’s not like we’re exclusive.`,-1),c[71]||=n(`blockquote`,null,[n(`p`,null,`有什么大不了的？我们又不是排他的。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`109.392`,duration:`13.68`}),c[72]||=a(),c[73]||=n(`strong`,null,`Chandler Bing:`,-1),c[74]||=a(` Look, Joey, Kathy is clearly not fulfilling your emotional needs. But Casey, I mean granted I only saw the back of her head, but I got this sense that she’s-she’s smart, and funny, and gets you.`,-1),c[75]||=n(`blockquote`,null,[n(`p`,null,`听着，乔伊，凯西显然没有满足你的情感需求。但是凯西，我的意思是，虽然我只看到了她的后脑勺，但我感觉到她——她聪明、有趣，能吸引你。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`123.072`,duration:`3.096`}),c[76]||=a(),c[77]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[78]||=a(` You got all that from the back of her head?`,-1),c[79]||=n(`blockquote`,null,[n(`p`,null,`你从她后脑勺里猜到的？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`126.168`,duration:`8.136`}),c[80]||=a(),c[81]||=n(`strong`,null,`Chandler Bing:`,-1),c[82]||=a(` All right look, I think it’s time for you to settle down. Y'know? Make a choice, pick a lane.`,-1),c[83]||=n(`blockquote`,null,[n(`p`,null,`好吧，听着，我想你该安定下来了。你知道吗？做个选择，选择一条小路。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`134.304`,duration:`1.8`}),c[84]||=a(),c[85]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[86]||=a(` Who’s Elaine?`,-1),c[87]||=n(`blockquote`,null,[n(`p`,null,`伊莲是谁？`)],-1),c[88]||=n(`hr`,null,null,-1),c[89]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Monica and Rachel's, Ross and Monica are sitting on the couch playing cards, and Phoebe is working on a new song.`)],-1),c[90]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`莫妮卡和瑞秋家，罗斯和莫妮卡坐在沙发上打牌，菲比正在创作一首新歌。`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`136.104`,duration:`9.144`}),c[91]||=a(),c[92]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[93]||=a(` (singing) "Little, tiny Tarzan, swinging on a nose hair. Swinging with the greatest of ease…" Darn it! Now, I don’t know who to get to the next verse.`,-1),c[94]||=n(`blockquote`,null,[n(`p`,null,`（唱）“小小的泰山，在鼻毛上摇摆。以最轻松的方式荡秋千……”该死！现在，我不知道谁能读到下一节。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`145.248`,duration:`8.496`}),c[95]||=a(),c[96]||=n(`strong`,null,`Ross Geller:`,-1),c[97]||=a(` Oh, you could just go uh, "greatest of ease… (plays air guitar) BAH-bah-bha-bhannn." Then go right into it.`,-1),c[98]||=n(`blockquote`,null,[n(`p`,null,`哦，你可以说，“最轻松的…（弹空气吉他）呸呸呸”然后就开始了。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`153.744`,duration:`5.784`}),c[99]||=a(),c[100]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[101]||=a(` Yeah, ooh, I like that! Yeah. Wait! How do you know about ‘bah-bah-bha-bhan?’`,-1),c[102]||=n(`blockquote`,null,[n(`p`,null,`是的，哦，我喜欢！是 啊等待你是怎么知道“巴巴巴”的`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`159.528`,duration:`3.216`}),c[103]||=a(),c[104]||=n(`strong`,null,`Ross Geller:`,-1),c[105]||=a(` Well umm, y’know, I used to play.`,-1),c[106]||=n(`blockquote`,null,[n(`p`,null,`嗯，你知道，我以前玩过。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`162.744`,duration:`2.376`}),c[107]||=a(),c[108]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[109]||=a(` Oh yeah, that’s right, the keyboards, huh?`,-1),c[110]||=n(`blockquote`,null,[n(`p`,null,`哦，是的，没错，键盘，嗯？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`165.12`,duration:`8.568`}),c[111]||=a(),c[112]||=n(`strong`,null,`Ross Geller:`,-1),c[113]||=a(` Yeah, just a little in high school, but then I really got into it in college. I mean that’s-that’s when I really found my sound.`,-1),c[114]||=n(`blockquote`,null,[n(`p`,null,`是的，高中的时候有一点，但后来我在大学里就开始学了。我是说，那是我真正找到声音的时候。`)],-1),c[115]||=n(`p`,null,[n(`em`,null,`(Monica is taking a drink as Ross says that, laughs, and snorts her drink.)`)],-1),c[116]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（莫妮卡在罗斯说的时候喝了一杯，笑了笑，喷了一口饮料。）`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`173.688`,duration:`10.104`}),c[117]||=a(),c[118]||=n(`strong`,null,`Monica Geller:`,-1),c[119]||=a(` Oh God! Orange juice just came out of my nose, but it was totally worth it. Oh my God, I completely forgot about your sound.`,-1),c[120]||=n(`blockquote`,null,[n(`p`,null,`哦，天哪！橙汁刚从我鼻子里流出来，但完全值得。天啊，我完全忘了你的声音。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`183.792`,duration:`1.368`}),c[121]||=a(),c[122]||=n(`strong`,null,`Ross Geller:`,-1),c[123]||=a(` Yeah.`,-1),c[124]||=n(`blockquote`,null,[n(`p`,null,`是的。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`185.16`,duration:`7.032`}),c[125]||=a(),c[126]||=n(`strong`,null,`Monica Geller:`,-1),c[127]||=a(` He used to lock himself in the basement for hours. No one was every allowed to hear, "The Sound."`,-1),c[128]||=n(`blockquote`,null,[n(`p`,null,`他过去常常把自己锁在地下室好几个小时。没有人被允许听到“声音”`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`192.192`,duration:`1.824`}),c[129]||=a(),c[130]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[131]||=a(` I wanna hear "The Sound."`,-1),c[132]||=n(`blockquote`,null,[n(`p`,null,`我想听“声音”`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`194.016`,duration:`9.624`}),c[133]||=a(),c[134]||=n(`strong`,null,`Ross Geller:`,-1),c[135]||=a(` Really? No. I mean, nah, I haven’t played in so long, and-and, well it’s-it’s really personal stuff, y’know?`,-1),c[136]||=n(`blockquote`,null,[n(`p`,null,`真的吗？不，我是说，不，我已经很久没玩了，而且，嗯，这真的是私人的东西，你知道吗？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`203.64`,duration:`2.784`}),c[137]||=a(),c[138]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[139]||=a(` Come on, play that funky music white boy.`,-1),c[140]||=n(`blockquote`,null,[n(`p`,null,`来吧，播放那个时髦的音乐，白人男孩。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`206.424`,duration:`1.416`}),c[141]||=a(),c[142]||=n(`strong`,null,`Monica Geller:`,-1),c[143]||=a(` Yeah!`,-1),c[144]||=n(`blockquote`,null,[n(`p`,null,`是啊！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`207.84`,duration:`6.48`}),c[145]||=a(),c[146]||=n(`strong`,null,`Ross Geller:`,-1),c[147]||=a(` No, you guys, I mean my keyboards are all the way up in—No, yeah, okay. (Runs out.)`,-1),c[148]||=n(`blockquote`,null,[n(`p`,null,`不，你们这些家伙，我是说我的键盘一路往上，不，是的，好的。（用完了。）`)],-1),c[149]||=n(`p`,null,`[Cut to later that same day, Ross has retrieved his keyboard and is about to debut, "The Sound."]`,-1),c[150]||=n(`blockquote`,null,[n(`p`,null,`[切换到当天晚些时候，罗斯已经找回了他的键盘，并将首次亮相《声音》。]`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`214.32`,duration:`2.232`}),c[151]||=a(),c[152]||=n(`strong`,null,`Ross Geller:`,-1),c[153]||=a(` Okay, guys.`,-1),c[154]||=n(`blockquote`,null,[n(`p`,null,`好的，伙计们。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`216.552`,duration:`3.792`}),c[155]||=a(),c[156]||=n(`strong`,null,`Chandler Bing:`,-1),c[157]||=a(` All right! Bring it on, you…`,-1),c[158]||=n(`blockquote`,null,[n(`p`,null,`好吧！来吧，你…`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`220.344`,duration:`17.208`}),c[159]||=a(),c[160]||=n(`strong`,null,`Ross Geller:`,-1),c[161]||=a(` Here we go. (Plays one note) Y’know, I’ve-I’ve never played my stuff for anyone before, so it’s important that-that you understand it’s about communicating very private emotions. (Plays another note) Y’know, umm, you should-you should think of umm, my work as wordless sound poems. That’s what I’m…`,-1),c[162]||=n(`blockquote`,null,[n(`p`,null,`开始了。（演奏一个音符）你知道，我以前从未为任何人演奏过我的作品，所以重要的是你要明白这是关于交流非常私人的情感。（弹奏另一个音符）你知道，嗯，你应该你应该把我的作品想象成无言的有声诗。这就是我…`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`237.552`,duration:`3.288`}),c[163]||=a(),c[164]||=n(`strong`,null,`Chandler Bing:`,-1),c[165]||=a(` (interrupting) Oh my God! Play!`,-1),c[166]||=n(`blockquote`,null,[n(`p`,null,`（打断）哦，我的天啊！玩`)],-1),c[167]||=n(`p`,null,[n(`em`,null,`(Ross starts to play. He plays a key that has a back beat sound attached to it. Over the background music he plays the sound of a barking dog, a mooing cow, a laser beam, someone coughing, a jackhammer, a doorbell, a police siren, a ray gun, breaking dishes, and for a closer he plays the sound of a loud crash. Basically, the music sucks.)`)],-1),c[168]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（罗斯开始弹奏。他弹奏一个键，键上有一个反拍声。在背景音乐中，他弹奏狗吠声、牛吠声、激光束、有人咳嗽声、手锤声、门铃声、警笛声、射线枪声、打碎碟子的声音，在走近时，他会弹奏一声巨响。基本上，音乐很糟糕。）`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`240.84`,duration:`3.48`}),c[169]||=a(),c[170]||=n(`strong`,null,`Monica Geller:`,-1),c[171]||=a(` (At a loss for words) Boy, that was-that was, umm… terrific.`,-1),c[172]||=n(`blockquote`,null,[n(`p`,null,`（不知所措）男孩，那是，嗯…太棒了。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`244.32`,duration:`2.184`}),c[173]||=a(),c[174]||=n(`strong`,null,`Chandler Bing:`,-1),c[175]||=a(` Really, bitchin’!`,-1),c[176]||=n(`blockquote`,null,[n(`p`,null,`真的，混蛋！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`246.504`,duration:`1.656`}),c[177]||=a(),c[178]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[179]||=a(` Wow, it was so—wow!`,-1),c[180]||=n(`blockquote`,null,[n(`p`,null,`哇，真是太哇了！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`248.16`,duration:`3.48`}),c[181]||=a(),c[182]||=n(`strong`,null,`Ross Geller:`,-1),c[183]||=a(` Really?! I mean, really?!!`,-1),c[184]||=n(`blockquote`,null,[n(`p`,null,`真的吗？！我是说，真的？！！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`251.64`,duration:`3.312`}),c[185]||=a(),c[186]||=n(`strong`,null,`Rachel Green:`,-1),c[187]||=a(` Yeah, I mean, you should play in public!`,-1),c[188]||=n(`blockquote`,null,[n(`p`,null,`是啊，我是说，你应该在公共场合玩！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`254.952`,duration:`22.176`}),c[189]||=a(),c[190]||=n(`strong`,null,`Ross Geller:`,-1),c[191]||=a(` Wow! Thanks, you guys. That’s uh—ohhh, I wanna, I wanna play you another piece! Umm! Uh-oh! I left my uh, helicopter sounds on another disk. I’ll be right back! Okay? (Runs to fetch them) This is so nice, I’m—I am so… (starts to break up and leaves)`,-1),c[192]||=n(`blockquote`,null,[n(`p`,null,`哇！谢谢你们。那是，哦，我想，我想再给你演奏一首！嗯！哦！我把直升机的声音放在另一个磁盘上了。我马上回来！可以（跑去接他们）这太好了，我…（开始分手离开）`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`277.128`,duration:`3.744`}),c[193]||=a(),c[194]||=n(`strong`,null,`Monica Geller:`,-1),c[195]||=a(` Oh God bless my dad sound proofing the basement!`,-1),c[196]||=n(`blockquote`,null,[n(`p`,null,`哦，上帝保佑我爸爸，地下室隔音！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`280.872`,duration:`4.296`}),c[197]||=a(),c[198]||=n(`strong`,null,`Rachel Green:`,-1),c[199]||=a(` Oh, I can’t believe I ever let him touch me with those fingers.`,-1),c[200]||=n(`blockquote`,null,[n(`p`,null,`哦，我真不敢相信我居然让他用手指碰我。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`285.168`,duration:`7.488`}),c[201]||=a(),c[202]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[203]||=a(` What are you guys talking about, I loved it! It was soo moving. Oh, plus it’s just, it’s so different from the stuff you usually hear.`,-1),c[204]||=n(`blockquote`,null,[n(`p`,null,`你们在说什么，我喜欢！这是苏移动。哦，而且它只是，它和你通常听到的东西很不一样。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`292.656`,duration:`2.448`}),c[205]||=a(),c[206]||=n(`strong`,null,`Chandler Bing:`,-1),c[207]||=a(` You mean like, music?`,-1),c[208]||=n(`blockquote`,null,[n(`p`,null,`你是说音乐？`)],-1),c[209]||=n(`hr`,null,null,-1),c[210]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Chandler and Joey's, Chandler is watching Yasmein Bleeth running on TV, and the duck starts quacking.`)],-1),c[211]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`钱德勒和乔伊家，钱德勒在电视上看亚斯迈因·布莱斯跑步，鸭子开始嘎嘎作响。`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`295.104`,duration:`6.984`}),c[212]||=a(),c[213]||=n(`strong`,null,`Chandler Bing:`,-1),c[214]||=a(` Yeah, I know what you’re thinkin’! Yes, yes, your breasts are just as firm and juicy.`,-1),c[215]||=n(`blockquote`,null,[n(`p`,null,`是啊，我知道你在想什么！是的，是的，你的乳房一样结实多汁。`)],-1),c[216]||=n(`p`,null,[n(`em`,null,`(There’s a knock on the door.)`)],-1),c[217]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（有人敲门。）`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`302.088`,duration:`1.536`}),c[218]||=a(),c[219]||=n(`strong`,null,`Chandler Bing:`,-1),c[220]||=a(` Come in!`,-1),c[221]||=n(`blockquote`,null,[n(`p`,null,`进来！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`303.624`,duration:`2.424`}),c[222]||=a(),c[223]||=n(`strong`,null,`Kathy:`,-1),c[224]||=a(` (entering) Hey! (sees what’s on TV) Oh God, is that Baywatch?`,-1),c[225]||=n(`blockquote`,null,[n(`p`,null,`（进来）嘿！（看电视）哦，天哪，那是海滩手表吗？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`306.048`,duration:`4.488`}),c[226]||=a(),c[227]||=n(`strong`,null,`Chandler Bing:`,-1),c[228]||=a(` Uh yes, but uh, I just watch it for the articles.`,-1),c[229]||=n(`blockquote`,null,[n(`p`,null,`嗯，是的，但是，嗯，我只是看文章。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`310.536`,duration:`1.488`}),c[230]||=a(),c[231]||=n(`strong`,null,`Kathy:`,-1),c[232]||=a(` So is Joey around?`,-1),c[233]||=n(`blockquote`,null,[n(`p`,null,`乔伊在吗？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`312.024`,duration:`10.464`}),c[234]||=a(),c[235]||=n(`strong`,null,`Chandler Bing:`,-1),c[236]||=a(` No-no, he’s not back yet, but he’ll be here any minute. So uh, come on in. Have a seat. Bow or stern?`,-1),c[237]||=n(`blockquote`,null,[n(`p`,null,`不，不，他还没回来，但他随时都会来。所以，进来吧。请坐船头还是船尾？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`322.488`,duration:`3.048`}),c[238]||=a(),c[239]||=n(`strong`,null,`Kathy:`,-1),c[240]||=a(` I uh, don’t really have a preference. You?`,-1),c[241]||=n(`blockquote`,null,[n(`p`,null,`我，呃，真的没有偏好。你呢？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`325.536`,duration:`5.256`}),c[242]||=a(),c[243]||=n(`strong`,null,`Chandler Bing:`,-1),c[244]||=a(` I like it in the stern. (Realizes what he just said.) …of the boat. (The phone rings, and he answers it.) (on phone) Hello.`,-1),c[245]||=n(`blockquote`,null,[n(`p`,null,`我喜欢在船尾。（意识到他刚才所说的。）…船的。（电话铃响了，他接了。）（电话）你好。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`330.792`,duration:`6.432`}),c[246]||=a(),c[247]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[248]||=a(` (on the other end at a pay phone) Hey, it’s me. Listen Casey and I were on our way back and had a little car trouble.`,-1),c[249]||=n(`blockquote`,null,[n(`p`,null,`（在公用电话的另一端）嘿，是我。听着，凯西和我在回来的路上遇到了一点小麻烦。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`337.224`,duration:`1.728`}),c[250]||=a(),c[251]||=n(`strong`,null,`Chandler Bing:`,-1),c[252]||=a(` What happened?`,-1),c[253]||=n(`blockquote`,null,[n(`p`,null,`发生什么事了？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`338.952`,duration:`10.032`}),c[254]||=a(),c[255]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[256]||=a(` We broke down on the Parkway, so I have to walk back and get some transmission fluid. And hey, listen could you please tell Kathy that I’ll be there as soon as I can.`,-1),c[257]||=n(`blockquote`,null,[n(`p`,null,`我们在公园路上抛锚了，所以我得走回去买些变速器油。嘿，听着，你能告诉凯西我会尽快赶到的。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`348.984`,duration:`2.112`}),c[258]||=a(),c[259]||=n(`strong`,null,`Chandler Bing:`,-1),c[260]||=a(` Why can’t you tell her?`,-1),c[261]||=n(`blockquote`,null,[n(`p`,null,`你为什么不能告诉她？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`351.096`,duration:`4.152`}),c[262]||=a(),c[263]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[264]||=a(` ‘Cause I only have one quarter, and I think my time is about to—(he stops talking suddenly)`,-1),c[265]||=n(`blockquote`,null,[n(`p`,null,`因为我只有一刻钟，我想我的时间快到了——（他突然停止说话）`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`355.248`,duration:`2.976`}),c[266]||=a(),c[267]||=n(`strong`,null,`Chandler Bing:`,-1),c[268]||=a(` Joey! Joey!!`,-1),c[269]||=n(`blockquote`,null,[n(`p`,null,`乔伊！乔伊！！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`358.224`,duration:`1.488`}),c[270]||=a(),c[271]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[272]||=a(` Yeah?`,-1),c[273]||=n(`blockquote`,null,[n(`p`,null,`是吗？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`359.712`,duration:`2.52`}),c[274]||=a(),c[275]||=n(`strong`,null,`Chandler Bing:`,-1),c[276]||=a(` I thought your time ran out.`,-1),c[277]||=n(`blockquote`,null,[n(`p`,null,`我以为你的时间不多了。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`362.232`,duration:`3.48`}),c[278]||=a(),c[279]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[280]||=a(` Me too, but I guess I do have a couple of more—(his time runs out for real)`,-1),c[281]||=n(`blockquote`,null,[n(`p`,null,`我也是，但我想我还有两个（他的时间真的不多了）`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`365.712`,duration:`5.856`}),c[282]||=a(),c[283]||=n(`strong`,null,`Chandler Bing:`,-1),c[284]||=a(` (to Kathy) Uhh, that was Joey. He’s running a little late, he says he’s sorry.`,-1),c[285]||=n(`blockquote`,null,[n(`p`,null,`（对凯西）嗯，那是乔伊。他有点晚了，他说他很抱歉。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`371.568`,duration:`0.72`}),c[286]||=a(),c[287]||=n(`strong`,null,`Kathy:`,-1),c[288]||=a(` Oh.`,-1),c[289]||=n(`blockquote`,null,[n(`p`,null,`哦。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`372.288`,duration:`3.624`}),c[290]||=a(),c[291]||=n(`strong`,null,`Chandler Bing:`,-1),c[292]||=a(` So I guess it’s just uh, you and me then.`,-1),c[293]||=n(`blockquote`,null,[n(`p`,null,`所以我想那只是，呃，你和我。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`375.912`,duration:`1.008`}),c[294]||=a(),c[295]||=n(`strong`,null,`Kathy:`,-1),c[296]||=a(` Oh, okay.`,-1),c[297]||=n(`blockquote`,null,[n(`p`,null,`哦，好的。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`376.92`,duration:`2.4`}),c[298]||=a(),c[299]||=n(`strong`,null,`Chandler Bing:`,-1),c[300]||=a(` Yeah, I think it is!`,-1),c[301]||=n(`blockquote`,null,[n(`p`,null,`是的，我想是的！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`379.32`,duration:`1.368`}),c[302]||=a(),c[303]||=n(`strong`,null,`Kathy:`,-1),c[304]||=a(` So what did you do today?`,-1),c[305]||=n(`blockquote`,null,[n(`p`,null,`那你今天做了什么？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`380.688`,duration:`3.312`}),c[306]||=a(),c[307]||=n(`strong`,null,`Chandler Bing:`,-1),c[308]||=a(` Oh, I had an appointment to get my haircut…`,-1),c[309]||=n(`blockquote`,null,[n(`p`,null,`哦，我约好去理发了…`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`384.0`,duration:`1.224`}),c[310]||=a(),c[311]||=n(`strong`,null,`Kathy:`,-1),c[312]||=a(` (interrupting) Oh, it looks great!`,-1),c[313]||=n(`blockquote`,null,[n(`p`,null,`（打断）哦，看起来很棒！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`385.224`,duration:`2.352`}),c[314]||=a(),c[315]||=n(`strong`,null,`Chandler Bing:`,-1),c[316]||=a(` …and then it got canceled.`,-1),c[317]||=n(`blockquote`,null,[n(`p`,null,`……然后就取消了。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`387.576`,duration:`1.2`}),c[318]||=a(),c[319]||=n(`strong`,null,`Kathy:`,-1),c[320]||=a(` Well, I could cut it.`,-1),c[321]||=n(`blockquote`,null,[n(`p`,null,`嗯，我可以剪下来。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`388.776`,duration:`3.048`}),c[322]||=a(),c[323]||=n(`strong`,null,`Chandler Bing:`,-1),c[324]||=a(` Really?! You do that?`,-1),c[325]||=n(`blockquote`,null,[n(`p`,null,`真的吗？！你这么做？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`391.824`,duration:`4.824`}),c[326]||=a(),c[327]||=n(`strong`,null,`Kathy:`,-1),c[328]||=a(` Yeah, I do. Of course, I learned at my aunt’s dog grooming shop, but hey, what do you say?`,-1),c[329]||=n(`blockquote`,null,[n(`p`,null,`是的，我喜欢。当然，我是在我姑妈的狗美容店学的，但是嘿，你说呢？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`396.648`,duration:`5.448`}),c[330]||=a(),c[331]||=n(`strong`,null,`Chandler Bing:`,-1),c[332]||=a(` Dog grooming huh? Okay, just don’t make my tail too poofy.`,-1),c[333]||=n(`blockquote`,null,[n(`p`,null,`狗美容，嗯？好吧，别把我的尾巴弄得太小。`)],-1),c[334]||=n(`p`,null,`[Cut to later, Kathy is cutting Chandler’s hair.]`,-1),c[335]||=n(`blockquote`,null,[n(`p`,null,`[切到稍后，凯西正在给钱德勒理发。]`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`402.096`,duration:`1.704`}),c[336]||=a(),c[337]||=n(`strong`,null,`Kathy:`,-1),c[338]||=a(` You have really great hair.`,-1),c[339]||=n(`blockquote`,null,[n(`p`,null,`你的头发真漂亮。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`403.8`,duration:`7.608`}),c[340]||=a(),c[341]||=n(`strong`,null,`Chandler Bing:`,-1),c[342]||=a(` Well, thanks. I grow it myself. (Kathy is running her fingers through his hair, and Chandler catches himself enjoying it too much.) Y’know who also has great hair is Joey!`,-1),c[343]||=n(`blockquote`,null,[n(`p`,null,`嗯，谢谢。我自己种的。（凯西用手指抚摸他的头发，钱德勒发现自己太喜欢了。）你知道乔伊的头发也很棒！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`411.408`,duration:`7.104`}),c[344]||=a(),c[345]||=n(`strong`,null,`Kathy:`,-1),c[346]||=a(` Yes! Yeah! Joey has great hair! Umm, I’m basically done here. Just let me get this off your neck.`,-1),c[347]||=n(`blockquote`,null,[n(`p`,null,`是的！是 啊乔伊的头发很好！嗯，我基本上已经做完了。让我把这个从你脖子上拿下来。`)],-1),c[348]||=n(`p`,null,[n(`em`,null,`(Kathy leans in really close and Chandler mouths "Oh my God." She moves around in front of him and kneels at his feet.)`)],-1),c[349]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（凯西靠得很近，钱德勒说：“哦，我的天哪。”她在他面前走动，跪在他的脚边。）`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`418.512`,duration:`2.256`}),c[350]||=a(),c[351]||=n(`strong`,null,`Chandler Bing:`,-1),c[352]||=a(` What-what ‘cha doin’?`,-1),c[353]||=n(`blockquote`,null,[n(`p`,null,`你在干什么？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`420.768`,duration:`1.896`}),c[354]||=a(),c[355]||=n(`strong`,null,`Kathy:`,-1),c[356]||=a(` Checking to see if it’s even.`,-1),c[357]||=n(`blockquote`,null,[n(`p`,null,`看看是否公平。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`422.664`,duration:`1.464`}),c[358]||=a(),c[359]||=n(`strong`,null,`Chandler Bing:`,-1),c[360]||=a(` ‘Kay.`,-1),c[361]||=n(`blockquote`,null,[n(`p`,null,`“凯。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`424.128`,duration:`0.864`}),c[362]||=a(),c[363]||=n(`strong`,null,`Kathy:`,-1),c[364]||=a(` Looks good.`,-1),c[365]||=n(`blockquote`,null,[n(`p`,null,`看起来不错。`)],-1),c[366]||=n(`p`,null,[n(`em`,null,`(They lean in to kiss and are interrupted by the phone.)`)],-1),c[367]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（他们俯身亲吻，被电话打断。）`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`424.992`,duration:`5.832`}),c[368]||=a(),c[369]||=n(`strong`,null,`Chandler Bing:`,-1),c[370]||=a(` (jumping up to answer the phone) Oh the phone! The phone’s making sounds! (On phone) Hello!`,-1),c[371]||=n(`blockquote`,null,[n(`p`,null,`（跳起来接电话）哦，电话！电话响了！（电话）你好！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`430.824`,duration:`2.352`}),c[372]||=a(),c[373]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[374]||=a(` (on phone) Hey dude, it’s me.`,-1),c[375]||=n(`blockquote`,null,[n(`p`,null,`（打电话）嘿，伙计，是我。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`433.176`,duration:`1.968`}),c[376]||=a(),c[377]||=n(`strong`,null,`Chandler Bing:`,-1),c[378]||=a(` Hey it’s Joey!`,-1),c[379]||=n(`blockquote`,null,[n(`p`,null,`嘿，是乔伊！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`435.144`,duration:`10.488`}),c[380]||=a(),c[381]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[382]||=a(` Listen uh, I’m really sorry, it looks like I’m gonna be stuck here for a while. I got the transmission fluid, but when I went to put it in the car, the transmission wasn’t there!`,-1),c[383]||=n(`blockquote`,null,[n(`p`,null,`听着，呃，我真的很抱歉，看起来我要在这里呆一段时间了。我得到了变速器油，但当我把它放进车里时，变速器不在那里！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`445.632`,duration:`1.464`}),c[384]||=a(),c[385]||=n(`strong`,null,`Chandler Bing:`,-1),c[386]||=a(` What?`,-1),c[387]||=n(`blockquote`,null,[n(`p`,null,`什么？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`447.096`,duration:`6.0`}),c[388]||=a(),c[389]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[390]||=a(` Yeah, it must’ve fallen out a few blocks back. I just figured we hit a dog.`,-1),c[391]||=n(`blockquote`,null,[n(`p`,null,`是的，它一定是在几个街区后掉出来的。我只是觉得我们撞到了一条狗。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`453.096`,duration:`1.56`}),c[392]||=a(),c[393]||=n(`strong`,null,`Chandler Bing:`,-1),c[394]||=a(` Okay.`,-1),c[395]||=n(`blockquote`,null,[n(`p`,null,`好的。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`454.656`,duration:`4.2`}),c[396]||=a(),c[397]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[398]||=a(` Listen uh, could you put Kathy on, I wanna apologize.`,-1),c[399]||=n(`blockquote`,null,[n(`p`,null,`听着，你能帮凯西接电话吗，我想道歉。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`458.856`,duration:`3.312`}),c[400]||=a(),c[401]||=n(`strong`,null,`Chandler Bing:`,-1),c[402]||=a(` Oh yeah man. (to Kathy) Joey. (Hands her the phone.)`,-1),c[403]||=n(`blockquote`,null,[n(`p`,null,`哦，是的，伙计。（对凯西）乔伊。（把电话递给她。）`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`462.168`,duration:`9.288`}),c[404]||=a(),c[405]||=n(`strong`,null,`Kathy:`,-1),c[406]||=a(` (on phone) Hey. (listens) Oh no it’s fine, don’t worry about it. (listens) Yeah-no, stop apologizing, it’s okay. (listens) Yeah! I’ll talk to you tomorrow. (hangs up) (to Chandler) I should uh, probably go.`,-1),c[407]||=n(`blockquote`,null,[n(`p`,null,`（打电话）嘿。（听）哦，不，没关系，别担心。（听）是的，不，别道歉了，没事的。（听）是的！我明天和你谈谈。（挂断）（对钱德勒）我应该呃，也许该走了。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`471.456`,duration:`4.104`}),c[408]||=a(),c[409]||=n(`strong`,null,`Chandler Bing:`,-1),c[410]||=a(` Yeah. Yes! Yeah.`,-1),c[411]||=n(`blockquote`,null,[n(`p`,null,`是的。对是 啊`)],-1),c[412]||=n(`p`,null,[n(`em`,null,`(Kathy leaves and Chandler groans in agony. Kathy knocks on the door and Chandler opens it.)`)],-1),c[413]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（凯西离开，钱德勒痛苦地呻吟。凯西敲门，钱德勒开门。）`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`475.56`,duration:`1.488`}),c[414]||=a(),c[415]||=n(`strong`,null,`Kathy:`,-1),c[416]||=a(` I forgot my purse.`,-1),c[417]||=n(`blockquote`,null,[n(`p`,null,`我忘了带钱包。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`477.048`,duration:`1.368`}),c[418]||=a(),c[419]||=n(`strong`,null,`Chandler Bing:`,-1),c[420]||=a(` Oh.`,-1),c[421]||=n(`blockquote`,null,[n(`p`,null,`哦。`)],-1),c[422]||=n(`p`,null,[n(`em`,null,`(They kiss, passionately.)`)],-1),c[423]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（他们热情地接吻。）`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`478.416`,duration:`2.544`}),c[424]||=o(` <strong>Kathy:</strong> No, I really did forget my purse.<blockquote><p>不，我真的忘了带钱包。</p></blockquote><p><em>(They kiss again.)</em></p><blockquote><p><em>（他们又接吻了。）</em></p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Chandler and Joey&#39;s, continued from earlier. Chandler and Kathy are still kissing, then they stop suddenly.</em></p><blockquote><p>🎬 <em>钱德勒和乔伊的，从早些时候开始继续。钱德勒和凯西还在接吻，然后他们突然停了下来。</em></p></blockquote>`,11),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`480.96`,duration:`6.36`}),c[425]||=a(),c[426]||=n(`strong`,null,`Chandler Bing:`,-1),c[427]||=a(` No-no-no-no, this is bad! It’s bad! This is bad!`,-1),c[428]||=n(`blockquote`,null,[n(`p`,null,`不，不，这太糟糕了！真糟糕！这太糟糕了！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`487.32`,duration:`0.936`}),c[429]||=a(),c[430]||=n(`strong`,null,`Kathy:`,-1),c[431]||=a(` Horrible!`,-1),c[432]||=n(`blockquote`,null,[n(`p`,null,`太可怕了！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`488.256`,duration:`3.624`}),c[433]||=a(),c[434]||=n(`strong`,null,`Chandler Bing:`,-1),c[435]||=a(` Wait the uh, the kiss or the situation?`,-1),c[436]||=n(`blockquote`,null,[n(`p`,null,`等等，那个吻还是那个情况？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`491.88`,duration:`1.968`}),c[437]||=a(),c[438]||=n(`strong`,null,`Kathy:`,-1),c[439]||=a(` No-no-no, the kiss was good.`,-1),c[440]||=n(`blockquote`,null,[n(`p`,null,`不，不，这个吻很好。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`493.848`,duration:`1.608`}),c[441]||=a(),c[442]||=n(`strong`,null,`Chandler Bing:`,-1),c[443]||=a(` Okay!`,-1),c[444]||=n(`blockquote`,null,[n(`p`,null,`好的！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`495.456`,duration:`1.32`}),c[445]||=a(),c[446]||=n(`strong`,null,`Kathy:`,-1),c[447]||=a(` No, but that’s bad!`,-1),c[448]||=n(`blockquote`,null,[n(`p`,null,`不，但那很糟糕！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`496.776`,duration:`7.848`}),c[449]||=a(),c[450]||=n(`strong`,null,`Chandler Bing:`,-1),c[451]||=a(` Ooh! Yes! Okay! Here’s what we do, we-we forget it happened.`,-1),c[452]||=n(`blockquote`,null,[n(`p`,null,`哦！对可以这就是我们所做的，我们忘记了它的发生。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`504.624`,duration:`0.696`}),c[453]||=a(),c[454]||=n(`strong`,null,`Kathy:`,-1),c[455]||=a(` What?!`,-1),c[456]||=n(`blockquote`,null,[n(`p`,null,`什么？！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`505.32`,duration:`7.992`}),c[457]||=a(),c[458]||=n(`strong`,null,`Chandler Bing:`,-1),c[459]||=a(` Okay, we-we swallow our feelings. Even if it means we’re unhappy forever. Sound good?`,-1),c[460]||=n(`blockquote`,null,[n(`p`,null,`好吧，我们咽下我们的感觉。即使这意味着我们永远不快乐。听起来不错吧？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`513.312`,duration:`1.392`}),c[461]||=a(),c[462]||=n(`strong`,null,`Kathy:`,-1),c[463]||=a(` Can you really do that?`,-1),c[464]||=n(`blockquote`,null,[n(`p`,null,`你真的能做到吗？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`514.704`,duration:`4.224`}),c[465]||=a(),c[466]||=n(`strong`,null,`Chandler Bing:`,-1),c[467]||=a(` I have to; he’s my best friend, and you’re seeing him.`,-1),c[468]||=n(`blockquote`,null,[n(`p`,null,`我必须这么做；他是我最好的朋友，你正在和他约会。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`518.928`,duration:`2.712`}),c[469]||=a(),c[470]||=n(`strong`,null,`Kathy:`,-1),c[471]||=a(` Chandler, I like Joey a lot, but with you…`,-1),c[472]||=n(`blockquote`,null,[n(`p`,null,`钱德勒，我很喜欢乔伊，但和你在一起…`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`521.64`,duration:`9.072`}),c[473]||=a(),c[474]||=n(`strong`,null,`Chandler Bing:`,-1),c[475]||=a(` (interrupting) Oh-no-no-no! Don’t! Don’t! See-see, you’re getting me confused, I’m starting to urn.`,-1),c[476]||=n(`blockquote`,null,[n(`p`,null,`（打断）哦，不，不！不要！不要！瞧，你把我弄糊涂了，我开始发疯了。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`530.712`,duration:`4.224`}),c[477]||=a(),c[478]||=n(`strong`,null,`Kathy:`,-1),c[479]||=a(` I’m sorry. If you wanna pretend that nothing happened, I can try.`,-1),c[480]||=n(`blockquote`,null,[n(`p`,null,`对不起。如果你想假装什么都没发生，我可以试试。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`534.936`,duration:`2.568`}),c[481]||=a(),c[482]||=n(`strong`,null,`Chandler Bing:`,-1),c[483]||=a(` I-I think we have too.`,-1),c[484]||=n(`blockquote`,null,[n(`p`,null,`我想我们也是。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`537.504`,duration:`1.536`}),c[485]||=a(),c[486]||=n(`strong`,null,`Kathy:`,-1),c[487]||=a(` Okay. Bye.`,-1),c[488]||=n(`blockquote`,null,[n(`p`,null,`好的。再见。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`539.04`,duration:`3.384`}),c[489]||=a(),c[490]||=n(`strong`,null,`Chandler Bing:`,-1),c[491]||=a(` Bye. (Kathy leaves and Chandler wonders over to and leans up against the door.) Are you still out there?`,-1),c[492]||=n(`blockquote`,null,[n(`p`,null,`再见。（凯西离开了，钱德勒向门走去，靠在门上）你还在外面吗？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`542.424`,duration:`0.768`}),c[493]||=a(),c[494]||=n(`strong`,null,`Kathy:`,-1),c[495]||=a(` (outside the door) No. (Chandler opens the door and they kiss again.)`,-1),c[496]||=n(`blockquote`,null,[n(`p`,null,`（门外）不。（钱德勒打开门，他们又接吻了。）`)],-1),c[497]||=n(`hr`,null,null,-1),c[498]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Central Perk, Ross is performing, his music hasn’t improved.`)],-1),c[499]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`中央公园，罗斯正在表演，他的音乐没有改进。`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`543.192`,duration:`4.344`}),c[500]||=a(),c[501]||=n(`strong`,null,`Ross Geller:`,-1),c[502]||=a(` (His voice is altered to sound like a computer.) Electrifying. (He plays the sound of a ticking clock.) Emphatic time-time-time…`,-1),c[503]||=n(`blockquote`,null,[n(`p`,null,`（他的声音变了，听起来像电脑。）令人兴奋。（他播放时钟的滴答声）强调时间…`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`547.536`,duration:`3.816`}),c[504]||=a(),c[505]||=n(`strong`,null,`Monica Geller:`,-1),c[506]||=a(` (to Rachel and Phoebe) Y'know, there’s a Starbucks about three blocks down.`,-1),c[507]||=n(`blockquote`,null,[n(`p`,null,`（对瑞秋和菲比）你知道，三个街区外有一家星巴克。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`551.352`,duration:`4.08`}),c[508]||=a(),c[509]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[510]||=a(` (pushing Monica back onto the couch) It’s so inspired! Look at him! Look at him go!`,-1),c[511]||=n(`blockquote`,null,[n(`p`,null,`（把莫妮卡推回到沙发上）太有灵感了！看看他！看着他，走吧！`)],-1),c[512]||=n(`p`,null,`[cut back to Ross who finally finishes his so-called song with the same crash from before. He gets some applause, mainly ‘cause he’s done.]`,-1),c[513]||=n(`blockquote`,null,[n(`p`,null,`[回到罗斯身上，他最终以与之前相同的撞击声完成了他的所谓歌曲。他赢得了一些掌声，主要是因为他已经完成了。]`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`555.432`,duration:`2.496`}),c[514]||=a(),c[515]||=n(`strong`,null,`Ross Geller:`,-1),c[516]||=a(` (with the altered voice) Thank you guys-guys-guys…`,-1),c[517]||=n(`blockquote`,null,[n(`p`,null,`（声音变了）谢谢你们…`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`557.928`,duration:`2.544`}),c[518]||=a(),c[519]||=n(`strong`,null,`Monica Geller:`,-1),c[520]||=a(` (to Phoebe) Hey, aren’t you up next?`,-1),c[521]||=n(`blockquote`,null,[n(`p`,null,`（对菲比）嘿，你不是下一个吗？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`560.472`,duration:`2.016`}),c[522]||=a(),c[523]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[524]||=a(` Oh no, I’m not playing tonight.`,-1),c[525]||=n(`blockquote`,null,[n(`p`,null,`哦，不，我今晚不玩了。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`562.488`,duration:`1.68`}),c[526]||=a(),c[527]||=n(`strong`,null,`Rachel Green:`,-1),c[528]||=a(` Why not?`,-1),c[529]||=n(`blockquote`,null,[n(`p`,null,`为什么不呢？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`564.168`,duration:`5.952`}),c[530]||=a(),c[531]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[532]||=a(` I can’t follow Ross! It’d be like those bicycle ridding chimps that followed The Beetles. No.`,-1),c[533]||=n(`blockquote`,null,[n(`p`,null,`我跟不上罗斯！就像那些骑自行车的黑猩猩跟着甲虫一样。不`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`570.12`,duration:`2.52`}),c[534]||=a(),c[535]||=n(`strong`,null,`Monica Geller:`,-1),c[536]||=a(` Phoebe, Ross sucks!`,-1),c[537]||=n(`blockquote`,null,[n(`p`,null,`菲比，罗斯太差劲了！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`572.64`,duration:`3.432`}),c[538]||=a(),c[539]||=n(`strong`,null,`Rachel Green:`,-1),c[540]||=a(` Phoebe, the place has emptied because of him.`,-1),c[541]||=n(`blockquote`,null,[n(`p`,null,`菲比，因为他这个地方已经空了。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`576.072`,duration:`7.656`}),c[542]||=a(),c[543]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[544]||=a(` Oh my God, he’s not even appreciated in his own time. I would give anything to not be appreciated in my own time!`,-1),c[545]||=n(`blockquote`,null,[n(`p`,null,`哦，我的天啊，在他自己的时代，他甚至都不被赏识。我愿意付出任何在我自己的时间里不被欣赏的东西！`)],-1),c[546]||=n(`p`,null,[n(`em`,null,`(Rachel and Monica look at each other, and agree on something without saying anything.)`)],-1),c[547]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（瑞秋和莫妮卡面面相觑，一言不发地达成了一致。）`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`583.728`,duration:`4.368`}),c[548]||=a(),c[549]||=n(`strong`,null,`Monica Geller:`,-1),c[550]||=a(` Okay. Umm, Phoebe, you suck too.`,-1),c[551]||=n(`blockquote`,null,[n(`p`,null,`好的。菲比，你也很烂。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`588.096`,duration:`2.736`}),c[552]||=a(),c[553]||=n(`strong`,null,`Rachel Green:`,-1),c[554]||=a(` Yeah, Phoebe you’re… awful!`,-1),c[555]||=n(`blockquote`,null,[n(`p`,null,`是啊，菲比，你……糟透了！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`590.832`,duration:`2.232`}),c[556]||=a(),c[557]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[558]||=a(` You guys. You suck too. (She hugs them both.)`,-1),c[559]||=n(`blockquote`,null,[n(`p`,null,`你们这些家伙。你也很烂。（她拥抱了他们俩。）`)],-1),c[560]||=n(`hr`,null,null,-1),c[561]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Chandler and Joey's, Joey is opening the door, but Chandler has the chain on it.`)],-1),c[562]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`钱德勒和乔伊家，乔伊正在开门，但钱德勒的门上有锁链。`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`593.064`,duration:`4.92`}),c[563]||=a(),c[564]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[565]||=a(` Aww man! I can’t believe I locked myself out again! (He knocks on the door.)`,-1),c[566]||=n(`blockquote`,null,[n(`p`,null,`哇，老兄！真不敢相信我又把自己锁在外面了！（他敲门。）`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`597.984`,duration:`1.944`}),c[567]||=a(),c[568]||=n(`strong`,null,`Chandler Bing:`,-1),c[569]||=a(` Hang on buddy! (He goes over and unlocks the door and opens it to reveal a fully furnished apartment.)`,-1),c[570]||=n(`blockquote`,null,[n(`p`,null,`等等，伙计！（他走过去，打开门锁，打开门，看到一间家具齐全的公寓。）`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`599.928`,duration:`5.784`}),c[571]||=a(),c[572]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[573]||=a(` (rushing in) Oh my God! What happened here? Did you do all this?`,-1),c[574]||=n(`blockquote`,null,[n(`p`,null,`（冲进来）哦，天哪！这里发生了什么事？这些都是你干的吗？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`605.712`,duration:`1.848`}),c[575]||=a(),c[576]||=n(`strong`,null,`Chandler Bing:`,-1),c[577]||=a(` I sure did.`,-1),c[578]||=n(`blockquote`,null,[n(`p`,null,`是的。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`607.56`,duration:`1.488`}),c[579]||=a(),c[580]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[581]||=a(` Why?`,-1),c[582]||=n(`blockquote`,null,[n(`p`,null,`为什么？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`609.048`,duration:`4.944`}),c[583]||=a(),c[584]||=n(`strong`,null,`Chandler Bing:`,-1),c[585]||=a(` Well, I just thought it’d make me feel good to do something nice for my friend.`,-1),c[586]||=n(`blockquote`,null,[n(`p`,null,`嗯，我只是觉得为朋友做点好事会让我感觉很好。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`613.992`,duration:`2.304`}),c[587]||=a(),c[588]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[589]||=a(` Well, you’re amazing.`,-1),c[590]||=n(`blockquote`,null,[n(`p`,null,`嗯，你太棒了。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`616.296`,duration:`3.984`}),c[591]||=a(),c[592]||=n(`strong`,null,`Chandler Bing:`,-1),c[593]||=a(` Oh no-no-no. This is amazing. (He goes over and presses a button on a remote control that opens the entertainment center doors revealing the TV.)`,-1),c[594]||=n(`blockquote`,null,[n(`p`,null,`哦，不，不，这太棒了。（他走过去，按下遥控器上的一个按钮，打开娱乐中心的门，露出电视。）`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`620.28`,duration:`7.944`}),c[595]||=a(),c[596]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[597]||=a(` (very excited) A TV as if it appears from nowhere! That’s the dream! Man, how did you afford this stuff?`,-1),c[598]||=n(`blockquote`,null,[n(`p`,null,`（非常兴奋）一台电视好像不知从哪里冒出来的！这就是梦想！伙计，你怎么买得起这些东西？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`628.224`,duration:`5.664`}),c[599]||=a(),c[600]||=n(`strong`,null,`Chandler Bing:`,-1),c[601]||=a(` Well, y’know I’m 29. I mean who needs a savings account.`,-1),c[602]||=n(`blockquote`,null,[n(`p`,null,`嗯，你知道我29岁。我是说谁需要一个储蓄账户。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`633.888`,duration:`3.72`}),c[603]||=a(),c[604]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[605]||=a(` Oh, you are the best friends anyone has ever had.`,-1),c[606]||=n(`blockquote`,null,[n(`p`,null,`哦，你是有史以来最好的朋友。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`637.608`,duration:`2.208`}),c[607]||=a(),c[608]||=n(`strong`,null,`Chandler Bing:`,-1),c[609]||=a(` Oh, I don’t know.`,-1),c[610]||=n(`blockquote`,null,[n(`p`,null,`哦，我不知道。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`639.816`,duration:`10.752`}),c[611]||=a(),c[612]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[613]||=a(` Oh-no-no-no, you are! You do this, you give me the great advice, and hey listen, I was thinking about what you said yesterday about focusing on one woman, I’m gonna do that.`,-1),c[614]||=n(`blockquote`,null,[n(`p`,null,`哦，不，不，你是！你这样做，你给了我很好的建议，嘿，听着，我在想你昨天说的关于关注一个女人的话，我要这么做。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`650.568`,duration:`2.208`}),c[615]||=a(),c[616]||=n(`strong`,null,`Chandler Bing:`,-1),c[617]||=a(` You mean with Casey.`,-1),c[618]||=n(`blockquote`,null,[n(`p`,null,`你是说和凯西在一起。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`652.776`,duration:`5.904`}),c[619]||=a(),c[620]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[621]||=a(` No-no-no, I think I’m gonna see how things go with Kathy. She’s pretty cool.`,-1),c[622]||=n(`blockquote`,null,[n(`p`,null,`不，不，我想我要看看凯西的情况如何。她很酷。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`658.68`,duration:`1.8`}),c[623]||=a(),c[624]||=n(`strong`,null,`Chandler Bing:`,-1),c[625]||=a(` Or Casey.`,-1),c[626]||=n(`blockquote`,null,[n(`p`,null,`或者凯西。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`660.48`,duration:`2.256`}),c[627]||=a(),c[628]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[629]||=a(` No-no, Kathy.`,-1),c[630]||=n(`blockquote`,null,[n(`p`,null,`不，不，凯西。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`662.736`,duration:`1.944`}),c[631]||=a(),c[632]||=n(`strong`,null,`Chandler Bing:`,-1),c[633]||=a(` Could be Casey.`,-1),c[634]||=n(`blockquote`,null,[n(`p`,null,`可能是凯西。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`664.68`,duration:`3.552`}),c[635]||=a(),c[636]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[637]||=a(` No. No, Kathy.`,-1),c[638]||=n(`blockquote`,null,[n(`p`,null,`不，不，凯西。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`668.232`,duration:`2.112`}),c[639]||=a(),c[640]||=n(`strong`,null,`Chandler Bing:`,-1),c[641]||=a(` Consider Casey.`,-1),c[642]||=n(`blockquote`,null,[n(`p`,null,`考虑一下凯西。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`670.344`,duration:`9.552`}),c[643]||=a(),c[644]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[645]||=a(` Y’know what I think? I think somebody’s got a little crush on Casey. How ‘bout I fix you two up? What do you think?`,-1),c[646]||=n(`blockquote`,null,[n(`p`,null,`你知道我怎么想吗？我想有人迷恋上凯西了。我给你们俩安排一下怎么样？你怎么认为？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`679.896`,duration:`4.152`}),c[647]||=a(),c[648]||=n(`strong`,null,`Chandler Bing:`,-1),c[649]||=a(` That all the pieces of my life are falling right into place!`,-1),c[650]||=n(`blockquote`,null,[n(`p`,null,`我生活的每一部分都恰到好处！`)],-1),c[651]||=n(`hr`,null,null,-1),c[652]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Central Perk, Ross has just finished playing.`)],-1),c[653]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`中央公园，罗斯刚刚演奏完。`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`684.048`,duration:`1.44`}),c[654]||=a(),c[655]||=n(`strong`,null,`Ross Geller:`,-1),c[656]||=a(` (to Phoebe) Hey!`,-1),c[657]||=n(`blockquote`,null,[n(`p`,null,`（对菲比）嘿！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`685.488`,duration:`4.128`}),c[658]||=a(),c[659]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[660]||=a(` Hey! You were really great! You were really, really great!`,-1),c[661]||=n(`blockquote`,null,[n(`p`,null,`嘿！你真的很棒！你真的，真的很棒！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`689.616`,duration:`10.536`}),c[662]||=a(),c[663]||=n(`strong`,null,`Ross Geller:`,-1),c[664]||=a(` Oh, thanks, thanks. So Monica tells me that uh, you don’t want to play anymore because me and y'know my talent. Is that true?`,-1),c[665]||=n(`blockquote`,null,[n(`p`,null,`哦，谢谢，谢谢。莫妮卡告诉我，你不想再玩了，因为我和你都知道我的天赋。这是真的吗？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`700.152`,duration:`2.208`}),c[666]||=a(),c[667]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[668]||=a(` Well, kinda. Yeah. Yeah.`,-1),c[669]||=n(`blockquote`,null,[n(`p`,null,`嗯，有点。是 啊是 啊`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`702.36`,duration:`1.752`}),c[670]||=a(),c[671]||=n(`strong`,null,`Ross Geller:`,-1),c[672]||=a(` Pheebs…`,-1),c[673]||=n(`blockquote`,null,[n(`p`,null,`菲比…`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`704.112`,duration:`7.584`}),c[674]||=a(),c[675]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[676]||=a(` Yeah, I-I can’t—I mean y’know I was trying to be really y'know okay and upbeat about it, I just—I feel so dwarfed by your musical gift. I…`,-1),c[677]||=n(`blockquote`,null,[n(`p`,null,`是的，我，我不能，我的意思是，你知道我一直想表现得很好，很乐观，我只是，我觉得你的音乐天赋让我相形见绌。我…`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`711.696`,duration:`12.792`}),c[678]||=a(),c[679]||=n(`strong`,null,`Ross Geller:`,-1),c[680]||=a(` See but, Pheebs that-that is the exact opposite intent of my music. Y’know my music is-is meant to inspire, and if it bothers you this much, then I… I won’t play anymore.`,-1),c[681]||=n(`blockquote`,null,[n(`p`,null,`看，但是，菲比，这与我的音乐的意图完全相反。你知道我的音乐是为了激发灵感，如果它让你这么烦恼，那么我…我不会再演奏了。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`724.488`,duration:`7.08`}),c[682]||=a(),c[683]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[684]||=a(` Oh no. No-no-no, don’t do that! How could I live with myself if I knew I was depriving the world of your music.`,-1),c[685]||=n(`blockquote`,null,[n(`p`,null,`哦，不，不，不，不要那样做！如果我知道我剥夺了世界上你的音乐，我怎么能和自己生活在一起呢。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`731.568`,duration:`2.04`}),c[686]||=a(),c[687]||=n(`strong`,null,`Ross Geller:`,-1),c[688]||=a(` Yeah, okay.`,-1),c[689]||=n(`blockquote`,null,[n(`p`,null,`是的，好的。`)],-1),c[690]||=n(`hr`,null,null,-1),c[691]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Central Perk, Rachel and Monica are sitting on the couch and Phoebe is getting coffee as Chandler enters. Ross is also there.`)],-1),c[692]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`中央公园，瑞秋和莫妮卡坐在沙发上，钱德勒进来时菲比正在喝咖啡。罗斯也在那里。`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`733.608`,duration:`5.856`}),c[693]||=a(),c[694]||=n(`strong`,null,`Ross Geller:`,-1),c[695]||=a(` Hey Chandler! Saw the new furniture. Very nice.`,-1),c[696]||=n(`blockquote`,null,[n(`p`,null,`嘿，钱德勒！我看到了新家具。很不错的。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`739.464`,duration:`4.2`}),c[697]||=a(),c[698]||=n(`strong`,null,`Monica Geller:`,-1),c[699]||=a(` Yeah! Joey has the best boyfriend ever!`,-1),c[700]||=n(`blockquote`,null,[n(`p`,null,`是啊！乔伊有史以来最好的男朋友！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`743.664`,duration:`2.088`}),c[701]||=a(),c[702]||=n(`strong`,null,`Chandler Bing:`,-1),c[703]||=a(` I kissed Kathy.`,-1),c[704]||=n(`blockquote`,null,[n(`p`,null,`我吻了凯西。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`745.752`,duration:`1.44`}),c[705]||=a(),c[706]||=n(`strong`,null,`Ross Geller:`,-1),c[707]||=a(` What?`,-1),c[708]||=n(`blockquote`,null,[n(`p`,null,`什么？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`747.192`,duration:`1.944`}),c[709]||=a(),c[710]||=n(`strong`,null,`Monica Geller:`,-1),c[711]||=a(` Are you serious?`,-1),c[712]||=n(`blockquote`,null,[n(`p`,null,`你是认真的吗？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`749.136`,duration:`1.224`}),c[713]||=a(),c[714]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[715]||=a(` Does Joey know?`,-1),c[716]||=n(`blockquote`,null,[n(`p`,null,`乔伊知道吗？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`750.36`,duration:`5.4`}),c[717]||=a(),c[718]||=n(`strong`,null,`Chandler Bing:`,-1),c[719]||=a(` No. Is there anyway, anyway you think he’ll understand this?`,-1),c[720]||=n(`blockquote`,null,[n(`p`,null,`没有。不管怎样，你认为他会明白这一点吗？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`755.76`,duration:`6.168`}),c[721]||=a(),c[722]||=n(`strong`,null,`Monica Geller:`,-1),c[723]||=a(` You obviously haven’t screwed over a lot of your friends. (They all look at her) Which we all appreciate.`,-1),c[724]||=n(`blockquote`,null,[n(`p`,null,`很明显，你没有骗过很多朋友。（他们都看着她）我们都很感激。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`761.928`,duration:`8.52`}),c[725]||=a(),c[726]||=n(`strong`,null,`Ross Geller:`,-1),c[727]||=a(` No the-the sad thing is, if you had told him how you felt before you kissed her, knowing Joey, he probably just would’ve just stepped aside.`,-1),c[728]||=n(`blockquote`,null,[n(`p`,null,`不，可悲的是，如果你在吻她之前告诉他你的感受，认识乔伊的话，他很可能会走开。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`770.448`,duration:`7.296`}),c[729]||=a(),c[730]||=n(`strong`,null,`Chandler Bing:`,-1),c[731]||=a(` Oh, don’t say that! Don’t say that. That’s not true. Is it?`,-1),c[732]||=n(`blockquote`,null,[n(`p`,null,`哦，别这么说！别那么说。那不是真的。它是？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`777.744`,duration:`1.368`}),c[733]||=a(),c[734]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[735]||=a(` I think maybe, yeah.`,-1),c[736]||=n(`blockquote`,null,[n(`p`,null,`我想可能吧，是的。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`779.112`,duration:`1.824`}),c[737]||=a(),c[738]||=n(`strong`,null,`Monica Geller:`,-1),c[739]||=a(` He loves you.`,-1),c[740]||=n(`blockquote`,null,[n(`p`,null,`他爱你。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`780.936`,duration:`2.784`}),c[741]||=a(),c[742]||=n(`strong`,null,`Chandler Bing:`,-1),c[743]||=a(` Then why didn’t you tell me to do that?!!`,-1),c[744]||=n(`blockquote`,null,[n(`p`,null,`那你为什么不叫我这么做？！！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`783.72`,duration:`3.264`}),c[745]||=a(),c[746]||=n(`strong`,null,`Ross Geller:`,-1),c[747]||=a(` Well, I said-I said something to Phoebe.`,-1),c[748]||=n(`blockquote`,null,[n(`p`,null,`嗯，我对菲比说了些什么。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`786.984`,duration:`4.032`}),c[749]||=a(),c[750]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[751]||=a(` Yeah! No, that’s right. And I thought it was a really good idea.`,-1),c[752]||=n(`blockquote`,null,[n(`p`,null,`是啊！不，没错。我觉得这真是个好主意。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`791.016`,duration:`2.64`}),c[753]||=a(),c[754]||=n(`strong`,null,`Rachel Green:`,-1),c[755]||=a(` I know, I remember that!`,-1),c[756]||=n(`blockquote`,null,[n(`p`,null,`我知道，我记得！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`793.656`,duration:`2.112`}),c[757]||=a(),c[758]||=n(`strong`,null,`Monica Geller:`,-1),c[759]||=a(` I remember you did.`,-1),c[760]||=n(`blockquote`,null,[n(`p`,null,`我记得是你干的。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`795.768`,duration:`3.384`}),c[761]||=a(),c[762]||=n(`strong`,null,`Chandler Bing:`,-1),c[763]||=a(` God!! (Sits down in disgust.) What am I gonna do?!`,-1),c[764]||=n(`blockquote`,null,[n(`p`,null,`天哪！！（厌恶地坐下）我该怎么办？！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`799.152`,duration:`3.504`}),c[765]||=a(),c[766]||=n(`strong`,null,`Rachel Green:`,-1),c[767]||=a(` Well, Chandler, you’re gonna have to tell him.`,-1),c[768]||=n(`blockquote`,null,[n(`p`,null,`钱德勒，你得告诉他。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`802.656`,duration:`3.576`}),c[769]||=a(),c[770]||=n(`strong`,null,`Chandler Bing:`,-1),c[771]||=a(` Why?! Why do I have to tell him?!`,-1),c[772]||=n(`blockquote`,null,[n(`p`,null,`为什么？！为什么我要告诉他？！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`806.232`,duration:`1.92`}),c[773]||=a(),c[774]||=n(`strong`,null,`Rachel Green:`,-1),c[775]||=a(` Because you do.`,-1),c[776]||=n(`blockquote`,null,[n(`p`,null,`因为你知道。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`808.152`,duration:`1.992`}),c[777]||=a(),c[778]||=n(`strong`,null,`Chandler Bing:`,-1),c[779]||=a(` Yeah, I know.`,-1),c[780]||=n(`blockquote`,null,[n(`p`,null,`是的，我知道。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`810.144`,duration:`4.08`}),c[781]||=a(),c[782]||=n(`strong`,null,`Ross Geller:`,-1),c[783]||=a(` Hey, would it be okay if I wrote a song about this.`,-1),c[784]||=n(`blockquote`,null,[n(`p`,null,`嘿，如果我写一首关于这个的歌可以吗。`)],-1),c[785]||=n(`hr`,null,null,-1),c[786]||=n(`p`,null,[a(`🎬 `),n(`em`,null,`Chandler and Joey's, Joey is watching TV as Chandler enters.`)],-1),c[787]||=n(`blockquote`,null,[n(`p`,null,[a(`🎬 `),n(`em`,null,`钱德勒和乔伊家，钱德勒进来时乔伊正在看电视。`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`814.224`,duration:`1.44`}),c[788]||=a(),c[789]||=n(`strong`,null,`Chandler Bing:`,-1),c[790]||=a(` Hey!`,-1),c[791]||=n(`blockquote`,null,[n(`p`,null,`嘿！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`815.664`,duration:`3.816`}),c[792]||=a(),c[793]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[794]||=a(` Hey! Samboucha Margarita?`,-1),c[795]||=n(`blockquote`,null,[n(`p`,null,`嘿！三宝茶玛格丽塔？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`819.48`,duration:`2.088`}),c[796]||=a(),c[797]||=n(`strong`,null,`Chandler Bing:`,-1),c[798]||=a(` Is that a real thing?`,-1),c[799]||=n(`blockquote`,null,[n(`p`,null,`那是真的吗？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`821.568`,duration:`3.552`}),c[800]||=a(),c[801]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[802]||=a(` Well, we only had samboucha, so it is now.`,-1),c[803]||=n(`blockquote`,null,[n(`p`,null,`嗯，我们只有三宝茶，所以现在是。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`825.12`,duration:`5.64`}),c[804]||=a(),c[805]||=n(`strong`,null,`Chandler Bing:`,-1),c[806]||=a(` Listen ah, Joe, I-I need to, I need to talk to you about something.`,-1),c[807]||=n(`blockquote`,null,[n(`p`,null,`听着，乔，我需要，我需要和你谈谈一些事情。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`830.76`,duration:`1.656`}),c[808]||=a(),c[809]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[810]||=a(` What’s up?`,-1),c[811]||=n(`blockquote`,null,[n(`p`,null,`怎么了？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`832.416`,duration:`7.584`}),c[812]||=a(),c[813]||=n(`strong`,null,`Chandler Bing:`,-1),c[814]||=a(` It’s-it’s about Kathy. Umm, uh, I like her. I like her a lot actually.`,-1),c[815]||=n(`blockquote`,null,[n(`p`,null,`是关于凯西的。嗯，我喜欢她。事实上我很喜欢她。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`840.0`,duration:`1.632`}),c[816]||=a(),c[817]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[818]||=a(` You do?`,-1),c[819]||=n(`blockquote`,null,[n(`p`,null,`是吗？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`841.632`,duration:`1.392`}),c[820]||=a(),c[821]||=n(`strong`,null,`Chandler Bing:`,-1),c[822]||=a(` Yeah.`,-1),c[823]||=n(`blockquote`,null,[n(`p`,null,`是的。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`843.024`,duration:`5.688`}),c[824]||=a(),c[825]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[826]||=a(` Well, you’re timing couldn’t be better. She’s not my girlfriend anymore.`,-1),c[827]||=n(`blockquote`,null,[n(`p`,null,`嗯，你的时机太好了。她不再是我的女朋友了。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`848.712`,duration:`1.464`}),c[828]||=a(),c[829]||=n(`strong`,null,`Chandler Bing:`,-1),c[830]||=a(` What?`,-1),c[831]||=n(`blockquote`,null,[n(`p`,null,`什么？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`850.176`,duration:`2.52`}),c[832]||=a(),c[833]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[834]||=a(` Yeah, she broke up with me.`,-1),c[835]||=n(`blockquote`,null,[n(`p`,null,`是的，她和我分手了。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`852.696`,duration:`2.304`}),c[836]||=a(),c[837]||=n(`strong`,null,`Chandler Bing:`,-1),c[838]||=a(` Oh uh, when?`,-1),c[839]||=n(`blockquote`,null,[n(`p`,null,`哦，什么时候？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`855.0`,duration:`7.392`}),c[840]||=a(),c[841]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[842]||=a(` Just now, after acting class. At first I thought she was doing some kind of scene, that’s why I let people watch.`,-1),c[843]||=n(`blockquote`,null,[n(`p`,null,`刚才，表演课结束后。起初我以为她在拍什么戏，所以我才让别人看。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`862.392`,duration:`5.328`}),c[844]||=a(),c[845]||=n(`strong`,null,`Chandler Bing:`,-1),c[846]||=a(` Oh man, I am so sorry. Are, are you okay?`,-1),c[847]||=n(`blockquote`,null,[n(`p`,null,`哦，伙计，我很抱歉。你没事吧？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`867.72`,duration:`6.36`}),c[848]||=a(),c[849]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[850]||=a(` Well, I’ve been better. But, I’m all right. So you like her huh?`,-1),c[851]||=n(`blockquote`,null,[n(`p`,null,`嗯，我好多了。但是，我没事。所以你喜欢她？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`874.08`,duration:`3.888`}),c[852]||=a(),c[853]||=n(`strong`,null,`Chandler Bing:`,-1),c[854]||=a(` Yes, but I-I uh, don’t have too.`,-1),c[855]||=n(`blockquote`,null,[n(`p`,null,`是的，但是我，我，呃，没有太多。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`877.968`,duration:`3.168`}),c[856]||=a(),c[857]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[858]||=a(` No-no-no, no it’s uh, it’s okay.`,-1),c[859]||=n(`blockquote`,null,[n(`p`,null,`不，不，不，没事的。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`881.136`,duration:`1.392`}),c[860]||=a(),c[861]||=n(`strong`,null,`Chandler Bing:`,-1),c[862]||=a(` Yeah?`,-1),c[863]||=n(`blockquote`,null,[n(`p`,null,`是吗？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`882.528`,duration:`5.52`}),c[864]||=a(),c[865]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[866]||=a(` Yeah. You know why? ‘Cause you came to me first.`,-1),c[867]||=n(`blockquote`,null,[n(`p`,null,`是的。你知道为什么吗？”因为你先来找我。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`888.048`,duration:`3.384`}),c[868]||=a(),c[869]||=n(`strong`,null,`Chandler Bing:`,-1),c[870]||=a(` Well, I thought that would be the best thing to do.`,-1),c[871]||=n(`blockquote`,null,[n(`p`,null,`嗯，我想那是最好的办法。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`891.432`,duration:`10.56`}),c[872]||=a(),c[873]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[874]||=a(` But hey, listen just so you know, you might have you’re work cut out for you. ‘Cause when I talked to her, I kinda got the feeling that she’s into some other guy. So…`,-1),c[875]||=n(`blockquote`,null,[n(`p`,null,`但是嘿，听着，你要知道，你可能有适合你的工作因为当我和她说话的时候，我有点感觉她爱上了另一个男人。所以…`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`901.992`,duration:`7.824`}),c[876]||=a(),c[877]||=n(`strong`,null,`Chandler Bing:`,-1),c[878]||=a(` See uh, that’s-that’s actually what I wanted to talk to you about. I-I think I know who the other guy is.`,-1),c[879]||=n(`blockquote`,null,[n(`p`,null,`看，呃，这正是我想跟你说的。我想我知道另一个人是谁了。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`909.816`,duration:`1.464`}),c[880]||=a(),c[881]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[882]||=a(` Who?`,-1),c[883]||=n(`blockquote`,null,[n(`p`,null,`谁？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`911.28`,duration:`3.48`}),c[884]||=a(),c[885]||=n(`strong`,null,`Chandler Bing:`,-1),c[886]||=a(` It’s me. I’m the other guy.`,-1),c[887]||=n(`blockquote`,null,[n(`p`,null,`是我。我是另一个人。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`914.76`,duration:`1.488`}),c[888]||=a(),c[889]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[890]||=a(` What?`,-1),c[891]||=n(`blockquote`,null,[n(`p`,null,`什么？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`916.248`,duration:`6.768`}),c[892]||=a(),c[893]||=n(`strong`,null,`Chandler Bing:`,-1),c[894]||=a(` Yeah, I mean when you were late last night, Kathy and I got to talking, and one thing to another and…`,-1),c[895]||=n(`blockquote`,null,[n(`p`,null,`是的，我的意思是当你昨晚很晚的时候，凯西和我聊了起来，一件一件地聊，然后…`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`923.016`,duration:`3.744`}),c[896]||=a(),c[897]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[898]||=a(` And what?! Did you sleep with her?!`,-1),c[899]||=n(`blockquote`,null,[n(`p`,null,`那又怎样？！你和她上床了吗？！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`926.76`,duration:`6.24`}),c[900]||=a(),c[901]||=n(`strong`,null,`Chandler Bing:`,-1),c[902]||=a(` No! No! No! I just kissed her.`,-1),c[903]||=n(`blockquote`,null,[n(`p`,null,`不！不不我刚刚吻了她。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`933.0`,duration:`3.456`}),c[904]||=a(),c[905]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[906]||=a(` What?!! That’s even worse!!`,-1),c[907]||=n(`blockquote`,null,[n(`p`,null,`什么？！！那更糟！！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`936.456`,duration:`2.088`}),c[908]||=a(),c[909]||=n(`strong`,null,`Chandler Bing:`,-1),c[910]||=a(` How is that worse?!`,-1),c[911]||=n(`blockquote`,null,[n(`p`,null,`怎么会更糟？！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`938.544`,duration:`3.672`}),c[912]||=a(),c[913]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[914]||=a(` I don’t know! But it’s the same!`,-1),c[915]||=n(`blockquote`,null,[n(`p`,null,`我不知道！但它是一样的！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`942.216`,duration:`6.24`}),c[916]||=a(),c[917]||=n(`strong`,null,`Chandler Bing:`,-1),c[918]||=a(` Look, I’m sorry! But there’s nothing I can do, I think I’m in love with her!`,-1),c[919]||=n(`blockquote`,null,[n(`p`,null,`听着，我很抱歉！但我无能为力，我想我爱上她了！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`948.456`,duration:`6.384`}),c[920]||=a(),c[921]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[922]||=a(` Who cares?! You went behind my back! I would never do that to you!`,-1),c[923]||=n(`blockquote`,null,[n(`p`,null,`谁在乎？！你背着我！我决不会那样对你！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`954.84`,duration:`5.736`}),c[924]||=a(),c[925]||=n(`strong`,null,`Chandler Bing:`,-1),c[926]||=a(` You’re right, I have no excuses! I was totally over the line.`,-1),c[927]||=n(`blockquote`,null,[n(`p`,null,`你说得对，我没有借口！我太过分了。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`960.576`,duration:`8.664`}),c[928]||=a(),c[929]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[930]||=a(` Over the line?! You-you’re-you’re so far past the line, that you-you can’t even see the line! The line is a dot to you!`,-1),c[931]||=n(`blockquote`,null,[n(`p`,null,`越界？！你，你，你已经过了线太远了，你甚至看不到线！这条线对你来说是一个点！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`969.24`,duration:`8.64`}),c[932]||=a(),c[933]||=n(`strong`,null,`Chandler Bing:`,-1),c[934]||=a(` Yes. Yes! Right! And I feel horrible. You have to believe me!`,-1),c[935]||=n(`blockquote`,null,[n(`p`,null,`是的。对正确的！我感觉很糟糕。你必须相信我！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`977.88`,duration:`13.008`}),c[936]||=a(),c[937]||=n(`strong`,null,`Joey Tribbiani:`,-1),c[938]||=a(` Is that why you bought all this stuff?! (Chandler makes a face like "Well, kinda.") Well, y’know what I will not watch your TV, I will not listen to your stereo, and there’s a cinnamon raisin loaf in the new bread maker that I’m not gonna eat! You know why?!`,-1),c[939]||=n(`blockquote`,null,[n(`p`,null,`这就是你买这些东西的原因吗？！（钱德勒做了个“嗯，有点。”）好吧，你知道我不会看你的电视，我不会听你的立体声，而且新面包机里有一块肉桂葡萄干面包，我不会吃！你知道为什么吗？！`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`990.888`,duration:`2.232`}),c[940]||=a(),c[941]||=n(`strong`,null,`Chandler Bing:`,-1),c[942]||=a(` Probably because…`,-1),c[943]||=n(`blockquote`,null,[n(`p`,null,`可能是因为…`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`993.12`,duration:`12.456`}),c[944]||=o(` <strong>Joey Tribbiani:</strong> Because it’s all tainted with your betrayal. From now on this apartment is empty for me! And I’m not happy about you either. (The bread maker dings) Oh, and just so you know, I made that bread for you. (Joey walks into his bedroom and slams the door.)<blockquote><p>因为这一切都被你的背叛玷污了。从现在起，这间公寓对我来说是空的！我对你也不满意。（面包师傅叮叮）哦，你知道，我给你做了面包。（乔伊走进卧室，砰地关上门。）</p></blockquote><p>Closing Credits</p><blockquote><p>片尾字幕</p></blockquote><hr><p>🎬 <em>Central Perk, Ross is playing his music. Monica, Phoebe, and Rachel are sitting on the couch.</em></p><blockquote><p>🎬 <em>中央公园，罗斯在放音乐。莫妮卡、菲比和瑞秋坐在沙发上。</em></p></blockquote>`,9),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`1005.576`,duration:`3.528`}),c[945]||=a(),c[946]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[947]||=a(` Oh my God, he’s lost it. He’s totally lost it.`,-1),c[948]||=n(`blockquote`,null,[n(`p`,null,`哦，天哪，他把它弄丢了。他完全失去了它。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`1009.104`,duration:`1.464`}),c[949]||=a(),c[950]||=n(`strong`,null,`Monica Geller:`,-1),c[951]||=a(` (removing ear plugs) What?`,-1),c[952]||=n(`blockquote`,null,[n(`p`,null,`（取下耳塞）什么？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`1010.568`,duration:`7.104`}),c[953]||=a(),c[954]||=n(`strong`,null,`Rachel Green:`,-1),c[955]||=a(` Phoebe, his music could not get any worse. There are rats in the basement that are hanging themselves.`,-1),c[956]||=n(`blockquote`,null,[n(`p`,null,`菲比，他的音乐再糟糕不过了。地下室里有老鼠在上吊。`)],-1),c[957]||=n(`p`,null,[n(`em`,null,`(Ross finally finishes with the same crash, and gets some applause.)`)],-1),c[958]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（罗斯终于以同样的声音结束了比赛，赢得了一些掌声。）`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`1017.672`,duration:`9.24`}),c[959]||=a(),c[960]||=n(`strong`,null,`Ross Geller:`,-1),c[961]||=a(` Thank you, thanks. (Sits down next to the girls) Yeah, I lost it. Y’know, I’m not gonna play anymore, (to Phoebe) would you, can you finish my set?`,-1),c[962]||=n(`blockquote`,null,[n(`p`,null,`谢谢，谢谢。（坐在女孩旁边）是的，我把它弄丢了。你知道，我不会再玩了，（对菲比）你能，你能完成我的布景吗？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`1026.912`,duration:`3.48`}),c[963]||=a(),c[964]||=n(`strong`,null,`Phoebe Buffay:`,-1),c[965]||=a(` After that? Yeah! No, I mean if I can help.`,-1),c[966]||=n(`blockquote`,null,[n(`p`,null,`在那之后？是 啊不，我是说如果我能帮忙的话。`)],-1),c[967]||=n(`p`,null,[n(`em`,null,`(Phoebe gets up and goes to play, Ross goes over and sits down next to Monica and Rachel.)`)],-1),c[968]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（菲比站起来去玩，罗斯走过去坐在莫妮卡和瑞秋旁边。）`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`1030.392`,duration:`2.496`}),c[969]||=a(),c[970]||=n(`strong`,null,`Ross Geller:`,-1),c[971]||=a(` Yeah, like I could lose it.`,-1),c[972]||=n(`blockquote`,null,[n(`p`,null,`是啊，好像我会失去它。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`1032.888`,duration:`1.464`}),c[973]||=a(),c[974]||=n(`strong`,null,`Rachel Green:`,-1),c[975]||=a(` What?`,-1),c[976]||=n(`blockquote`,null,[n(`p`,null,`什么？`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`1034.352`,duration:`2.952`}),c[977]||=a(),c[978]||=n(`strong`,null,`Ross Geller:`,-1),c[979]||=a(` I played bad on purpose guys.`,-1),c[980]||=n(`blockquote`,null,[n(`p`,null,`我故意扮演坏人。`)],-1),c[981]||=n(`p`,null,[n(`em`,null,`(Both Monica and Rachel laugh.)`)],-1),c[982]||=n(`blockquote`,null,[n(`p`,null,[n(`em`,null,`（莫妮卡和瑞秋都笑了。）`)])],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`1037.304`,duration:`3.84`}),c[983]||=a(),c[984]||=n(`strong`,null,`Monica Geller:`,-1),c[985]||=a(` Okay, so you were trying to play bad this whole time.`,-1),c[986]||=n(`blockquote`,null,[n(`p`,null,`好吧，所以你一直都想装坏。`)],-1),i(m,{src:`/audio/episodes/S04/S04E07.mp3`,start:`1041.144`,duration:`3.312`}),c[987]||=a(),c[988]||=n(`strong`,null,`Ross Geller:`,-1),c[989]||=a(` Yeah—no, just that last song.`,-1),c[990]||=n(`blockquote`,null,[n(`p`,null,`是的，不，只是最后一首歌。`)],-1)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};